create extension if not exists pgcrypto;
create table if not exists users(id uuid primary key default gen_random_uuid(),name text not null,email text not null unique,whatsapp text not null,username text not null unique,password_hash text not null,role text not null default 'student' check(role in('student','admin')),is_blocked boolean not null default false,blocked_until timestamptz,created_at timestamptz not null default now(),last_login_at timestamptz);
create table if not exists courses(id uuid primary key default gen_random_uuid(),title text not null,slug text not null unique,description text not null,category text not null,level text not null default 'Beginner',duration_minutes integer not null default 0,thumbnail_url text,ai_context text not null default '',published boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists lessons(id uuid primary key default gen_random_uuid(),course_id uuid not null references courses(id) on delete cascade,title text not null,slug text not null,position integer not null default 0,duration_minutes integer not null default 0,video_url text,content text not null default '',published boolean not null default false,unique(course_id,slug));
create table if not exists enrollments(id uuid primary key default gen_random_uuid(),user_id uuid not null references users(id) on delete cascade,course_id uuid not null references courses(id) on delete cascade,granted_by uuid references users(id),created_at timestamptz not null default now(),revoked_at timestamptz,unique(user_id,course_id));
create table if not exists lesson_progress(id uuid primary key default gen_random_uuid(),user_id uuid not null references users(id) on delete cascade,lesson_id uuid not null references lessons(id) on delete cascade,completed boolean not null default false,updated_at timestamptz not null default now(),unique(user_id,lesson_id));
create table if not exists audit_logs(id uuid primary key default gen_random_uuid(),user_id uuid references users(id) on delete set null,action text not null,ip text,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table if not exists security_events(id uuid primary key default gen_random_uuid(),user_id uuid references users(id) on delete set null,event_type text not null,severity text not null default 'medium',ip text,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index if not exists audit_logs_user_idx on audit_logs(user_id,created_at desc);
create index if not exists security_events_user_idx on security_events(user_id,created_at desc);
create index if not exists enrollments_user_idx on enrollments(user_id,revoked_at);
insert into courses(title,slug,description,category,level,duration_minutes,published,ai_context) values('SOC Analyst Foundations','soc-foundations','Alert triage, SIEM thinking, incident response, false positives and defensive workflows.','SOC','Beginner',360,true,'A beginner SOC course focused on alert triage, SIEM, false positives, IOCs, incident response and practical defensive thinking.') on conflict(slug) do nothing;
insert into courses(title,slug,description,category,level,duration_minutes,published,ai_context) values('Digital Forensics Fundamentals','digital-forensics','A practical foundation for evidence handling, disk artifacts, memory and network triage.','Forensics','Beginner',420,true,'A digital forensics foundation covering acquisition concepts, artifacts, memory forensics, PCAP triage and reporting.') on conflict(slug) do nothing;
insert into courses(title,slug,description,category,level,duration_minutes,published,ai_context) values('Python for Cybersecurity','python-cybersecurity','Python fundamentals applied to automation, APIs and defensive security workflows.','Programming','Beginner',300,true,'Python for cybersecurity automation, REST APIs, parsing, file handling and defensive scripting.') on conflict(slug) do nothing;
